<script>import {snapshot,clock,selected} from '../state.js';import Badge from './Badge.svelte';import Check from './Check.svelte';import Icon from './Icon.svelte';import {nodeState,shortStatus,bytes} from '../lib.js';export let nodes=[];export let detailed=false;</script>
<div class="table-scroll"><table class="node-table"><thead><tr><th>ノード</th><th>状態</th><th>CQL応答</th><th>ノード間TCP</th>{#if detailed}<th>観測エージェント</th><th>DC / Rack</th>{/if}<th class="numeric">データ量</th><th><span class="sr-only">詳細</span></th></tr></thead><tbody>
{#each nodes as n (n.host_id||n.id)}<tr data-row-id={n.id}><td><button class="node-name" onclick={()=>selected.set({kind:'node',id:n.id})}><span class="dot {nodeState(n,$snapshot,$clock)}"></span><span><strong>{n.name||n.address}</strong><small class="mono">{n.address}</small></span></button></td><td><Badge state={nodeState(n,$snapshot,$clock)} text={shortStatus(n)}/></td><td><Check value={n.cql} ttl={$snapshot?.stale_after_seconds} timings/></td><td><Check value={n.internode} ttl={$snapshot?.stale_after_seconds}/></td>{#if detailed}<td><Check value={n.watch_api} ttl={$snapshot?.stale_after_seconds}/></td><td class="quiet">{n.dc||'—'} / {n.rack||'—'}</td>{/if}<td class="numeric mono">{n.load_known&&n.metadata_known?bytes(n.load_bytes):'—'}</td><td><button class="icon-button" aria-label={`${n.name}を開く`} onclick={()=>selected.set({kind:'node',id:n.id})}><Icon name="chevron" size={14}/></button></td></tr>{:else}<tr><td colspan={detailed?8:6} class="empty-row">表示するノードがありません</td></tr>{/each}
</tbody></table></div>
